(7482792, 1190395, 63218, '<td valign="top">Oh I love that scarlet color. And the almost perfect symmetrical design. I opened it to max size &amp; it''s smooth &amp; clear, nice sharp curves. This turned out really well. Good title. Thank you.</td>', 'Oh I love that scarlet color. And the almost perfect symmetrical design. I opened it to max size & it''s smooth & clear, nice sharp curves. This turned out really well. Good title. Thank you.', '2016-11-15 23:18:01.000000', NULL, 1),
(7482810, 1190676, 63218, '<td valign="top">How delightfully 18th century this is--every painterly inch. Delightful. Thank you.</td>', 'How delightfully 18th century this is--every painterly inch. Delightful. Thank you.', '2016-11-16 00:06:15.000000', NULL, 1),
(7482841, 1190616, 63218, '<td valign="top">Wow. How did you do it? Somehow you took a camera with you when you time-traveled to the 19th century. And you brought back this clean, clear shot. And only that one horse noticed you. And the gentlemen appear to have naked knees. Wow!</td>', 'Wow. How did you do it? Somehow you took a camera with you when you time-traveled to the 19th century. And you brought back this clean, clear shot. And only that one horse noticed you. And the gentlemen appear to have naked knees. Wow!', '2016-11-16 11:51:02.000000', NULL, 1),
(7482842, 1190681, 63218, '<td valign="top">This is amazing for the mix of conflicting emotions I experience when I look at it. Almost as if you, all the people in this shot, all events &amp; people it took to lead up to this moment--were meant to converge at this moment so you could get this shot, PP it perfectly,  &amp; post it here for me to see &amp; experience. And now the rest of my existence is affected by this butterfly''s wing. Sorry if this sounds a little over-the-top. I''m not even drinking.<br/> <br/>Thank you.</td>', 'This is amazing for the mix of conflicting emotions I experience when I look at it. Almost as if you, all the people in this shot, all events & people it took to lead up to this moment--were meant to converge at this moment so you could get this shot, PP it perfectly,  & post it here for me to see & experience. And now the rest of my existence is affected by this butterfly''s wing. Sorry if this sounds a little over-the-top. I''m not even drinking. Thank you.', '2016-11-16 11:51:35.000000', NULL, 1),
(7482878, 1190543, 182284, '<td valign="top">Um, Wait a minute and I''ll google him. 10</td>', 'Um, Wait a minute and I''ll google him. 10', '2016-11-16 17:17:01.000000', NULL, 1),
